    --chat-bg-color: #000000 !important;
    --bubble-me-bg: #0a84ff !important;
    --bubble-me-color: #ffffff !important;
    --bubble-them-bg: #262629 !important;
    --bubble-them-color: #f5f5f7 !important;
    --bubble-them-border: none !important; /* 👈 夜间绝不要白描边 */
    --text-main: #f5f5f7 !important;
    --text-sub: #98989d !important;

    /* 暗夜高质感液态玻璃 */
