/* =========================================================
   4. 消息气泡与小尾巴 (去描边 + 紧凑间距版)
   ========================================================= */
.msg-bubble-container::before, .msg-bubble-container::after { display: none !important; }
.msg-bubble-wrapper, .msg-content-stack, .msg-bubble-container, .bubble-me-custom, .bubble-them-custom {
  overflow: visible !important;
}
.msg-me { padding-right: 12px !important; }
.msg-them { padding-left: 12px !important; }
.msg-content-stack {
  max-width: 280px !important; min-width: 80px !important; width: auto !important;
}
.bubble-me-custom, .bubble-them-custom {
  max-width: 100% !important;
}

.msg-bubble-wrapper { 
  margin-bottom: var(--bubble-gap-same) !important; 
}
.msg-bubble-wrapper.is-last, 
.msg-bubble-wrapper.is-single { 
  margin-bottom: var(--bubble-gap-diff) !important; 
}

/* 气泡本体：强制无任何边框！ */
.bubble-me-custom, .bubble-them-custom {
  position: relative !important; 
  isolation: isolate !important; 
  border-radius: 18px !important; 
  padding: var(--bubble-padding) !important; 
