.bubble-me-custom.first::before, .bubble-me-custom.mid::before { display: none !important; }

/* --- 对方小尾巴 --- */
.bubble-them-custom::before {
  content: "" !important; position: absolute !important;
  width: 20px !important; height: 20px !important;
  bottom: 0px !important; left: -8px !important;
