.msg-bubble-wrapper.is-last .bubble-them-custom::before, .msg-bubble-wrapper.is-single .bubble-them-custom::before,
[data-last="true"] .bubble-them-custom::before { display: block !important; }
.bubble-them-custom.first::before, .bubble-them-custom.mid::before { display: none !important; }

/* =========================================================
   4.1 【打字状态 & 特殊卡片 彻底掐灭小尾巴 (含视频卡片最高优先级)】
   ========================================================= */
.bubble-them-custom.msg-streaming,
.bubble-them-custom:has([class*="typing"]),
.bubble-them-custom:has([class*="dot"]),
.msg-bubble-wrapper.is-streaming .bubble-them-custom,
