.bubble-me-custom:has([class*="videocall"])::after,
.bubble-them-custom:has(.msg-transfer-card)::before,
.bubble-them-custom:has(.msg-transfer-card)::after,
.bubble-them-custom:has(.msg-redpacket-card)::before,
.bubble-them-custom:has(.msg-redpacket-card)::after,
.bubble-them-custom:has(.gift-ig-container)::before,
.bubble-them-custom:has(.gift-ig-container)::after,
.bubble-them-custom:has(.msg-sim-card)::before,
.bubble-them-custom:has(.msg-sim-card)::after,
.bubble-them-custom:has(.msg-loc-card)::before,
.bubble-them-custom:has(.msg-loc-card)::after,
.bubble-them-custom:has(.msg-videocall-card)::before,
.bubble-them-custom:has(.msg-videocall-card)::after,
.bubble-them-custom:has([class*="videocall"])::before,
.bubble-them-custom:has([class*="videocall"])::after,
.msg-bubble-wrapper:has(.msg-transfer-card) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.msg-redpacket-card) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.gift-ig-container) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.msg-sim-card) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.msg-loc-card) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.msg-videocall-card) .bubble-me-custom::before,
.msg-bubble-wrapper:has([class*="videocall"]) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.msg-sim-card) .bubble-them-custom::before,
