/* 行容器做参照 */
.chat-detail-screen .msg-bubble-wrapper.msg-them {
  position: relative !important;
}

/* 气泡整体下移 */
.chat-detail-screen .msg-bubble-wrapper.msg-them .bubble-them-custom {
  position: relative !important;
  top: 13px !important;
}

/* 折叠态：脱流，占住气泡下移空出的缝，不推气泡 */
.chat-detail-screen .msg-bubble-wrapper.msg-them .nuo-thinking-wrap:not(.is-open) {
  position: absolute !important;
  left: 0 !important;
  bottom: calc(100% - 13px) !important;
  margin: 0 !important;
  z-index: 6 !important;
}

/* 展开态：回归正常流，按原逻辑把气泡往下推 */
.chat-detail-screen .msg-bubble-wrapper.msg-them .nuo-thinking-wrap.is-open {
  position: static !important;
  margin-bottom: 2px !important;
}

/* ===== 消息间距 ===== */
:root{
  --nj-gap-in:6px;          /* 同一个人连发，气泡之间（每一条都一样） */
  --nj-gap-them-end:20px;    /* 对方说完 → 换我说 */
  --nj-gap-me-end:37px;      /* 我说完 → 换对方说（对方头像会稍微高出气泡，所以更宽） */
  --nj-gap-react:16px;       /* 有表情反应的消息额外多留的空 */
}

/* 所有消息行：先统一成连发间距 */
.msg-bubble-wrapper{
  margin-bottom:var(--nj-gap-in) !important;
}
.msg-bubble-wrapper.has-reactions{
  margin-bottom:calc(var(--nj-gap-in) + var(--nj-gap-react)) !important;
}

/* 每组最后一条（或单独一条）：和下一组之间，单独覆盖 */
.msg-bubble-wrapper.msg-them:is(.is-last,.is-single){
  margin-bottom:var(--nj-gap-them-end) !important;
}
.msg-bubble-wrapper.msg-me:is(.is-last,.is-single){
  margin-bottom:var(--nj-gap-me-end) !important;
}
